const cfg = $json;
if (cfg.confirmRightsAndConsent !== true) throw new Error('Confirm processing rights and any required speaker consent before running');
let parsed;
try { parsed = new URL(String(cfg.mediaUrl || '')); } catch { throw new Error('Use one valid public HTTPS media URL'); }
const host = parsed.hostname.toLowerCase();
if (parsed.protocol !== 'https:' || parsed.username || parsed.password || !host.includes('.') || host === 'localhost' || host.endsWith('.local') || host.endsWith('.internal') || /^10\.|^127\.|^169\.254\.|^192\.168\.|^172\.(1[6-9]|2[0-9]|3[01])\./.test(host)) throw new Error('Use one public HTTPS media URL without embedded credentials');
const language = String(cfg.language || 'pt').toLowerCase();
if (!/^[a-z]{2,3}$/.test(language)) throw new Error('Language must be a two-to-three-letter ISO code');
const maxDurationMinutes = Number(cfg.maxDurationMinutes);
if (!Number.isInteger(maxDurationMinutes) || maxDurationMinutes < 1 || maxDurationMinutes > 20) throw new Error('Duration must be between 1 and 20 minutes');
return [{json:{sources:[parsed.toString()],language,diarization:true,output_formats:['json','srt','vtt','txt'],maxDurationMinutes,integrationSource:'n8n-c157-support-call-review'}}];

const expected = $('Validate consent URL and limits').first().json;
const rows = $input.all().flatMap((item) => Array.isArray(item.json) ? item.json : [item.json]);
if (rows.length !== 1) throw new Error('Expected exactly one transcription result');
const row = rows[0];
if (row.url !== expected.sources[0] || row.integrationSource !== expected.integrationSource || typeof row.text !== 'string' || !Array.isArray(row.segments) || !row.files || typeof row.files !== 'object' || !Number.isInteger(row.charged_minutes) || row.charged_minutes < 1 || row.charged_minutes > expected.maxDurationMinutes) throw new Error('The Actor response failed semantic validation');
return [{json:row}];
